332	  e.preventDefault();
333	  const input = document.getElementById("file-input");
334	  const file = input.files[0];
335	  const btn = document.getElementById("submit-btn");
336	  if (!file) {
337	    showReport('<div class="banner bad">请先选择 CSV 文件。</div>');
338	    return;
339	  }
340	  btn.disabled = true;
341	  try {
342	    const res = await fetch("/api/clients/import", {method: "POST", body: file});
343	    const data = await res.json();
344	    renderReport(data, res.status);
345	    if (res.ok) {
346	      await loadClients();
