355	function renderReport(data, status) {
356	  if (status === 400) {
357	    showReport('<div class="banner bad">整份文件已拒绝导入，本次没有新增客户，原有客户资料保持原样。<br>原因：' +
358	      esc(data.error || "未知错误") + '</div>');
359	    return;
360	  }
361	  const failures = data.failures || [];
362	  let out = '<div class="banner ok">新增 <b>' + esc(data.imported_count) + '</b> 条，' +
363	    '未导入 <b>' + failures.length + '</b> 条。</div>';
364	  if (failures.length) {
365	    out += '<div class="failures"><p><b>未导入记录（编号按原文件数据记录，表头不计入）：</b></p><ul>';
366	    out += failures.map(f =>
367	      "<li>第 <b>" + esc(f.row) + "</b> 条：" + esc(f.reason) + "</li>").join("");
368	    out += "</ul></div>";
369	  }
370	  showReport(out);
371	}
372	
373	loadClients();
374	</script>
375	</body>
376	</html>
377	'''
